import json
from pathlib import Path
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
paths = sorted(Path('world/pages').glob('reviews-*.json'))
for path in paths:
    data = json.loads(path.read_text(encoding='utf-8'))
    def records(value):
        if isinstance(value, dict):
            if value.get('subject') == 'site:shopify-catalogue-example' and value.get('digest') == digest:
                yield {key: value.get(key) for key in ('seq', 'subject', 'digest', 'verdict', 'host_provider', 'host_turn')}
            for child in value.values():
                yield from records(child)
        elif isinstance(value, list):
            for child in value:
                yield from records(child)
    for record in records(data):
        print(json.dumps(record))
print('Review pages inspected:', len(paths))
